def n_permute_r(n, r):
    return math.factorial(n) // math.factorial(n - r)

print(n_permute_r(5, 2))   # 20, ways to arrange 2 items chosen from 5

def permutations_with_duplicates(n, *group_sizes):
    result = math.factorial(n)
    for size in group_sizes:
        result //= math.factorial(size)
    return result

print(permutations_with_duplicates(5, 2, 3))   # arrangements of AABBB-style patterns with repeats

def circular_permutations(n):
    return math.factorial(n - 1)

print(circular_permutations(4))   # 6, seating 4 people around a circular table
